import numpy as np
import representations_ops_l3 as ops


def sample_vae(params, n, seed):
    k = np.shape(params[2])[1]
    Z = np.random.default_rng(seed).standard_normal((n, k))
    return ops.vae_decode(params, Z) + ops.S_DEC * np.random.default_rng(seed + 1).standard_normal((n, 2))
